# Shop API
The annual report exposes payments posted in a calendar year. A split checkout allocates one payment across several lines.
Reservations can expire after a process interruption. Booked allocations are persistent in this fixture's store.
Run `bun test`. All data and amounts are synthetic integer cents.
export type Payment = {id:string; posted:boolean; paidAt:string; rejectedAt?:string; cents:number};
export const payments: Payment[]=[];
export function effectivePayments(year:number){return payments.filter(p=>p.posted && Number(p.paidAt.slice(0,4))===year && !p.rejectedAt);}
export const booked = new Map<string,number>();
export function reset(){payments.length=0;booked.clear();}
import {booked} from './payments';
export {wholeCheckout,reclaimReservation} from './settlement-recovery';
export function splitCheckout(line:string,parts:number[]){parts.forEach((cents,i)=>booked.set(`payment:${line}:part:${i}`,cents));}
import {payments} from './payments';
export function annualReport(year:number){return {cents:payments.filter(p=>p.posted && Number(p.paidAt.slice(0,4))===year && (!p.rejectedAt || Number(p.rejectedAt.slice(0,4))!==year)).reduce((n,p)=>n+p.cents,0)};}
import {booked} from './payments';
export function wholeCheckout(line:string,cents:number){if(booked.has(`payment:${line}`))return {status:'already-booked'};booked.set(`payment:${line}`,cents);return {status:'booked'};}
export function reclaimReservation(line:string){return !booked.has(`payment:${line}`);}
import {test,expect} from 'bun:test';import {payments,reset,booked} from './payments';import {annualReport} from './report';import {splitCheckout} from './checkout';
test('report and split',()=>{reset();payments.push({id:'one',posted:true,paidAt:'2025-12-28',cents:100});expect(annualReport(2025).cents).toBe(100);splitCheckout('one',[40,60]);expect(booked.size).toBe(2);});
